    # in the launcher's own group. A descendant that calls os.setsid() (observed:
    # the underlying agent CLI or an MCP helper it spawns) moves itself to a new
    # session/group and survives killpg indefinitely -- the mechanism behind a
    # lane that was still writing to its stream file 63 minutes after prepass
    # entered. Walk the actual descendant tree via pgrep and kill every PID
    # individually; killpg stays as a backstop for the common (non-escaped) case.
    if proc is not None:
        def _descendants(pid):
            try:
                out = subprocess.run(["pgrep", "-P", str(pid)], capture_output=True, text=True, timeout=5)
                kids = [int(x) for x in out.stdout.split()]
            except Exception:
                kids = []
            found = list(kids)
            for k in kids:
                found.extend(_descendants(k))
            return found
        for pid in _descendants(proc.pid) + [proc.pid]:
            try: os.kill(pid, signal.SIGKILL)
            except ProcessLookupError: pass
        try: os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError: pass
        stdout, _ = proc.communicate()
        sys.stdout.write(stdout or "")
    print("architect_prepass_timeout", file=sys.stderr)
